const ACLRuleParser={async generateOptimizedRule(state,helpers){const parts=[];const hasInclusions=state.grantedCategories.size>0||state.grantedCommands.size>0;let grantedCommands=null;if(hasInclusions){grantedCommands=await helpers.getCommandsGrantedByInclusions();}
state.orderedTerms.forEach(term=>{if(term.type==='category'){if(term.operation==='grant'){parts.push(`+@${term.value}`);}else if(term.operation==='block'){if(!hasInclusions||helpers.categoryOverlapsWithGranted(term.value,grantedCommands)){parts.push(`-@${term.value}`);}}}else if(term.type==='command'){if(term.operation==='grant'){parts.push(`+${term.value}`);}else if(term.operation==='block'){if(!hasInclusions||(grantedCommands&&grantedCommands.has(term.value))){parts.push(`-${term.value}`);}}}});if(state.keyPatterns){Array.from(state.keyPatterns).forEach(pattern=>{parts.push(pattern);});}
if(state.channelPatterns){Array.from(state.channelPatterns).forEach(pattern=>{parts.push(pattern);});}
if(state.selectors&&state.selectors.length>0){for(const selector of state.selectors){const selectorParts=[];selector.orderedTerms.forEach(term=>{if(term.type==='category'){selectorParts.push(term.operation==='grant'?`+@${term.value}`:`-@${term.value}`);}else if(term.type==='command'){selectorParts.push(term.operation==='grant'?`+${term.value}`:`-${term.value}`);}});if(selector.keyPatterns){Array.from(selector.keyPatterns).forEach(pattern=>{selectorParts.push(pattern);});}
if(selector.channelPatterns){Array.from(selector.channelPatterns).forEach(pattern=>{selectorParts.push(pattern);});}
if(selectorParts.length>0){parts.push(`(${selectorParts.join(' ')})`);}}}
return parts.join(' ');},async getCommandsGrantedByInclusions(state,getCommandsGrantedByCategories){const grantedCommands=new Set();state.grantedCommands.forEach(command=>{grantedCommands.add(command);});if(state.grantedCategories.size>0){try{const categoryCommands=await getCommandsGrantedByCategories();categoryCommands.forEach(command=>{grantedCommands.add(command);});}catch(error){console.error('Error getting category commands:',error);}}
return grantedCommands;},async getCommandsBlockedByCategories(state,API,AppState){if(state.blockedCategories.size===0){return[];}
const blockedCommands=new Set();for(const category of state.blockedCategories){try{const result=await API.parseRule(`+@${category}`,AppState.currentVersion);if(result&&result.success&&result.granted_commands){result.granted_commands.forEach(cmd=>blockedCommands.add(cmd));}}catch(error){console.error(`Error getting commands for blocked category ${category}:`,error);}}
return Array.from(blockedCommands);},categoryOverlapsWithGranted(_category,_grantedCommands){return true;}};export default ACLRuleParser;